UPDATE sys_user
SET nickname = #{nickname}, avatar_file_id = #{avatarFileId}, remark = #{remark},

        province_codes = #{provinceCodes,typeHandler=com.baomidou.mybatisplus.extension.handlers.JacksonTypeHandler},

    update_user_id = #{updateUserId}
WHERE uuid = #{uuid}

UPDATE sys_user
SET email = #{email}, update_user_id = #{uuid}
WHERE uuid = #{uuid}
